/**
 * Thêm giải thích tiếng Việt cho các câu lớp 5 chưa có explanation.
 */
const { PrismaClient } = require('@prisma/client');
const p = new PrismaClient();

const EXPL = {
// ═══ TOÁN ════
'số lớn nhất có 5 chữ số là:':'Số có 5 chữ số lớn nhất là khi tất cả các chữ số đều là 9: 99 999. Số 100 000 đã là số có 6 chữ số.',
'3/4 + 1/4 = ?':'Cộng hai phân số cùng mẫu số: giữ nguyên mẫu, cộng tử số: 3+1=4, kết quả là 4/4 = 1.',
'diện tích hình chữ nhật có chiều dài 8 cm, chiều rộng 5 cm là:':'S = dài × rộng = 8 × 5 = 40 cm². Không nhầm với chu vi (P = 2 × (8+5) = 26 cm).',
'0,5 = ?':'0,5 có một chữ số thập phân nên mẫu số là 10: 0,5 = 5/10. Rút gọn được 1/2.',
'1 tấn = ? kg':'1 tấn = 1 000 kg. Đây là đơn vị đo khối lượng cơ bản cần nhớ.',
'chu vi hình vuông có cạnh 7 cm là:':'Chu vi hình vuông = 4 × cạnh = 4 × 7 = 28 cm.',
'5/8 của 40 là:':'5/8 của 40 = 40 × 5 ÷ 8 = 200 ÷ 8 = 25.',
'12 345 × 0 = ?':'Bất kỳ số nào nhân với 0 đều bằng 0. Đây là tính chất của phép nhân.',
'tìm x: x × 6 = 54':'x = 54 ÷ 6 = 9. Kiểm tra: 9 × 6 = 54 ✓',
'1 giờ 30 phút = ? phút':'1 giờ = 60 phút; 1 giờ 30 phút = 60 + 30 = 90 phút.',
'số thập phân 3,07 đọc là:':'3,07 đọc là "ba phẩy không bảy". Chữ số 0 ở hàng phần mười phải đọc ra.',
'2/5 + 1/3 = ?':'Quy đồng mẫu số: 2/5 = 6/15; 1/3 = 5/15. Kết quả: 6/15 + 5/15 = 11/15.',
'diện tích hình tam giác có đáy 10 cm, chiều cao 6 cm là:':'S tam giác = (đáy × chiều cao) ÷ 2 = (10 × 6) ÷ 2 = 60 ÷ 2 = 30 cm².',
'75% = ?':'75% = 75/100 = 0,75. Chia cho 100 = dịch dấu phẩy sang trái 2 chữ số.',
'số nào chia hết cho cả 2 và 5?':'Chia hết cho 2: số chẵn (tận cùng 0,2,4,6,8). Chia hết cho 5: tận cùng 0 hoặc 5. Vừa chia hết cho 2 và 5: tận cùng bằng 0. Số 30 tận cùng bằng 0 ✓',
'4,5 km = ? m':'1 km = 1 000 m, nên 4,5 km = 4,5 × 1 000 = 4 500 m.',
'tổng của 3/7 và 4/7 là:':'Cùng mẫu số 7: 3/7 + 4/7 = 7/7 = 1.',
'một cửa hàng bán 240 kg gạo trong 4 ngày. trung bình mỗi ngày bán bao nhiêu kg?':'Trung bình mỗi ngày = 240 ÷ 4 = 60 kg.',
'1,25 × 4 = ?':'1,25 × 4 = 1,25 + 1,25 + 1,25 + 1,25 = 5. Hoặc: 1,25 × 4 = 5/4 × 4 = 5.',
'số nào là số nguyên tố?':'Số nguyên tố là số chỉ chia hết cho 1 và chính nó. 11 = 11 × 1 (chỉ có 2 ước). 9 = 3×3, 15 = 3×5, 21 = 3×7 đều không phải.',
'phân số tối giản của 12/18 là:':'ƯCLN(12, 18) = 6. 12÷6 = 2; 18÷6 = 3 → 2/3 là phân số tối giản.',
'thể tích hình hộp chữ nhật dài 4 cm, rộng 3 cm, cao 5 cm là:':'V = dài × rộng × cao = 4 × 3 × 5 = 60 cm³.',
'5,6 ÷ 0,7 = ?':'5,6 ÷ 0,7 = 56 ÷ 7 = 8 (nhân cả hai với 10 để khử số thập phân).',
'tìm x: 2/3 × x = 8':'x = 8 ÷ (2/3) = 8 × (3/2) = 24/2 = 12.',
'góc vuông có số đo bằng:':'Góc vuông = 90°. Góc thẳng = 180°, góc nhọn < 90°, góc tù 90° < α < 180°.',
'3/4 > 2/3. khẳng định này:':'Quy đồng: 3/4 = 9/12; 2/3 = 8/12. Vì 9/12 > 8/12 nên 3/4 > 2/3 là đúng.',
'1 lít = ? ml':'1 lít = 1 000 ml. Đây là đơn vị đo thể tích cơ bản.',
'số thập phân nào lớn hơn? 0,9 hay 0,89?':'0,9 = 0,90 và 0,89. So sánh từ hàng phần mười: 9 > 8 nên 0,9 > 0,89.',
'lớp 5a có 35 học sinh, 60% là nữ. số học sinh nữ là:':'Số nữ = 35 × 60% = 35 × 0,6 = 21 học sinh.',
'đường kính hình tròn gấp đôi:':'Đường kính (d) = 2 × bán kính (r). Vậy đường kính gấp đôi bán kính.',

// ═══ TIẾNG VIỆT ════
'từ nào dưới đây là danh từ?':'Danh từ là từ chỉ người, vật, sự vật. "Học sinh" chỉ người → danh từ. "Chạy" là động từ, "đẹp" là tính từ, "nhanh" là trạng từ.',
'câu "bầu trời xanh biếc." thuộc kiểu câu gì?':'Câu kể dùng để kể, tả, nhận xét; kết thúc bằng dấu chấm. "Bầu trời xanh biếc" là câu kể.',
'từ "mặt trời" có nghĩa gốc là:':'Nghĩa gốc (nghĩa đen) của "mặt trời" là thiên thể phát sáng và nhiệt. Đây là nghĩa xuất hiện đầu tiên của từ.',
'điền vào chỗ trống: "những cánh _____ đang bay lượn trên bầu trời." (chim / con chim)':'Khi nói số nhiều và không định (những), dùng danh từ chỉ loài: "chim". "Con chim" dùng cho một con cụ thể.',
'từ nào là tính từ?':'Tính từ chỉ đặc điểm, tính chất. "Xinh đẹp" là tính từ mô tả đặc điểm ngoại hình. "Học" là động từ, "sách" là danh từ, "chạy" là động từ.',
'dấu chấm lửng (...) trong câu thường dùng để:':'Dấu chấm lửng (...) biểu thị câu nói bỏ dở, ngập ngừng hoặc ý còn tiếp tục ngụ ý.',
'trong câu "nam học bài rất chăm chỉ", bộ phận vị ngữ là:':'"Nam" là chủ ngữ. Vị ngữ là bộ phận còn lại trả lời câu hỏi "làm gì/như thế nào?": "học bài rất chăm chỉ".',
'từ "xuân" trong "mùa xuân" và "tuổi xuân" có quan hệ gì?':'"Mùa xuân" = mùa đầu năm (nghĩa gốc); "tuổi xuân" = tuổi trẻ (nghĩa chuyển). Cùng một từ, nhiều nghĩa → từ nhiều nghĩa.',
'câu ghép là câu có:':'Câu ghép có từ hai cụm chủ - vị trở lên, các vế liên kết nhau bằng quan hệ từ hoặc dấu phẩy.',
'"nhà" trong "nhà trường" có nghĩa là gì?':'"Nhà trường" = tổ chức/cơ sở giáo dục. Đây là nghĩa chuyển của "nhà" (không phải công trình để ở).',
'từ nào sau đây là từ láy?':'"Lung linh" là từ láy âm (l-l). "Sách vở" và "đất nước" là từ ghép tổng hợp, "lao động" là từ ghép phân loại.',
'nghĩa của thành ngữ "có công mài sắt có ngày nên kim" là:':'Câu này ý nói: kiên trì nỗ lực (mài sắt) sẽ đạt kết quả (thành kim). Nghĩa là sự bền bỉ sẽ thành công.',
'từ "trắng" trong "trắng tay" mang nghĩa:':'"Trắng tay" là thành ngữ nghĩa chuyển: không còn gì, mất tất cả. Không phải nghĩa màu sắc.',
'dấu hai chấm (:) được dùng để:':'Dấu hai chấm báo hiệu phần tiếp theo là giải thích hoặc liệt kê.',
'chủ ngữ trong câu "những bông hoa hồng nở rộ trong vườn" là:':'Chủ ngữ trả lời câu hỏi "ai/cái gì". "Những bông hoa hồng" là cụm danh từ làm chủ ngữ.',
'từ nào sau đây là động từ?':'"Nhảy" là động từ chỉ hành động. "Buồn" là tính từ, "xanh" là tính từ, "bạn bè" là danh từ.',
'phép tu từ nào được dùng trong câu: "mặt trời là trái tim của vũ trụ"?':'Ẩn dụ: gọi Mặt Trời bằng "trái tim của vũ trụ" — dùng tên vật này thay tên vật khác dựa trên nét tương đồng (quan trọng, cần thiết).',
'từ đồng nghĩa với "dũng cảm" là:':'"Gan dạ" có nghĩa tương tự "dũng cảm" — không sợ nguy hiểm. "Nhút nhát" là trái nghĩa, "lười biếng/hiền lành" khác nghĩa.',
'câu "bạn có thể giúp mình không?" thuộc kiểu câu:':'Câu hỏi dùng để hỏi, kết thúc bằng dấu hỏi (?) hoặc có từ hỏi như "không?", "chưa?"...',
'từ trái nghĩa với "rộng lượng" là:':'"Hẹp hòi" (ích kỷ, không bao dung) là trái nghĩa của "rộng lượng" (bao dung, độ lượng).',
'biện pháp tu từ trong câu "dòng sông uốn mình qua cánh đồng như một dải lụa" là:':'So sánh: dùng từ "như" để so sánh dòng sông với dải lụa dựa trên hình dạng cong và mềm mại.',
'văn bản "dế mèn phiêu lưu ký" của tác giả nào?':'Tác phẩm "Dế Mèn phiêu lưu ký" là của nhà văn Tô Hoài, một tác phẩm thiếu nhi nổi tiếng Việt Nam.',
'từ "xanh" trong "da trời xanh" và "xanh lòng" là:':'"Da trời xanh" = màu xanh (nghĩa gốc); "xanh lòng" = chưa trưởng thành/còn non trẻ (nghĩa chuyển). → Từ nhiều nghĩa.',
'từ ngữ nào dùng sai trong câu: "bạn lan học rất siêng năng và chuyên cần."?':'"Siêng năng" và "chuyên cần" đều có nghĩa chăm chỉ, dùng đúng. Câu không có từ dùng sai.',
'trong câu ghép "vì trời mưa nên chúng tôi ở nhà", quan hệ giữa hai vế là:': '"Vì...nên..." là cặp quan hệ từ chỉ nguyên nhân - kết quả: vì trời mưa (nguyên nhân) nên ở nhà (kết quả).',
'từ "lòng" trong "lòng nhân ái" chỉ:': '"Lòng nhân ái" = tình cảm yêu thương. Ở đây "lòng" mang nghĩa chuyển: tình cảm, tâm hồn.',
'"yêu nước" là từ ghép thuộc loại:': '"Yêu nước" = yêu + nước, hai tiếng hợp nghĩa thành khái niệm chung (tình yêu với tổ quốc) → từ ghép tổng hợp.',
'câu tục ngữ "một cây làm chẳng nên non / ba cây chụm lại nên hòn núi cao" nói về:':'Tục ngữ này ý nói: một mình yếu (một cây), đoàn kết nhiều người thì mạnh (ba cây chụm lại) → sức mạnh đoàn kết.',
'dấu ngoặc kép ("...") dùng để:':'Dấu ngoặc kép trích dẫn lời nói hoặc đánh dấu từ ngữ dùng với nghĩa đặc biệt, từ lạ.',
'thành phần phụ trạng ngữ trong câu "sáng sớm, em đến trường" là:': '"Sáng sớm" là trạng ngữ chỉ thời gian — trả lời câu hỏi "khi nào?". Đứng đầu câu và cách chủ ngữ bằng dấu phẩy.',

// ═══ KHOA HỌC ════
'cây xanh thực hiện quang hợp nhờ:':'Diệp lục tố (chlorophyll) trong lá hấp thụ ánh sáng mặt trời để thực hiện quang hợp — biến CO₂ và nước thành chất hữu cơ và oxy.',
'chất nào chiếm tỉ lệ lớn nhất trong không khí?':'Không khí gồm khoảng 78% Nitơ (N₂) và 21% Oxy (O₂), còn lại là các khí khác. Nitơ chiếm nhiều nhất.',
'sự sinh sản của thực vật có hoa chủ yếu qua:':'Thực vật có hoa sinh sản chủ yếu qua hạt — từ hoa thụ phấn → quả → hạt → cây mới.',
'nước sôi ở nhiệt độ nào (ở điều kiện bình thường)?':'Ở điều kiện bình thường (áp suất khí quyển 1 atm), nước sôi ở 100°C.',
'động vật nào dưới đây là động vật máu lạnh?':'Rắn là bò sát — động vật máu lạnh (thân nhiệt thay đổi theo môi trường). Chó, mèo, thỏ là động vật có vú — máu nóng.',
'không khí cần cho sự cháy nhờ khí:':'Oxy (O₂) là khí duy trì sự cháy. Thiếu oxy, lửa tắt. Nitơ và CO₂ làm tắt lửa.',
'cơ quan nào của cơ thể người điều tiết nhiệt độ qua mồ hôi?':'Da có tuyến mồ hôi, khi mồ hôi bay hơi giúp làm mát cơ thể và điều tiết nhiệt độ.',
'sự bay hơi của nước xảy ra khi:':'Bay hơi là quá trình nước chuyển từ thể lỏng sang thể hơi (ở bề mặt, không cần sôi).',
'thực vật hút nước và khoáng chất nhờ:':'Rễ hút nước và khoáng chất từ đất. Lông hút (trên rễ) là bộ phận hấp thụ chính.',
'hiện tượng nào sau đây là hiện tượng vật lý?':'Nước đóng băng là hiện tượng vật lý — chỉ thay đổi trạng thái, không tạo ra chất mới. Sắt gỉ, than cháy, lên men là hiện tượng hóa học.',
'năng lượng mặt trời chủ yếu đến trái đất dưới dạng:':'Năng lượng mặt trời truyền đến Trái Đất dưới dạng bức xạ điện từ — chủ yếu là nhiệt và ánh sáng.',
'con người cần không khí để:':'Con người hít oxy từ không khí để thở (hô hấp tế bào), giải phóng năng lượng cho hoạt động sống.',
'loại đất nào giữ nước tốt nhất?':'Đất sét có hạt nhỏ, khe rỗng nhỏ nên giữ nước tốt nhất. Đất cát có khe rỗng lớn, nước thoát nhanh.',
'điện mặt trời sử dụng năng lượng từ:':'Pin mặt trời chuyển đổi ánh sáng mặt trời thành điện năng thông qua hiệu ứng quang điện.',
'con người thuộc lớp động vật nào?':'Con người thuộc lớp Thú (động vật có vú — Mammalia): nuôi con bằng sữa, có lông mao, máu nóng.',
'hiện tượng nào gây ô nhiễm không khí?':'Đốt rác thải ra khói bụi, CO₂, SO₂ — gây ô nhiễm không khí nghiêm trọng.',
'chất nào tan trong nước tạo thành dung dịch?':'Muối (NaCl) tan hoàn toàn trong nước tạo dung dịch đồng nhất. Cát, dầu ăn không tan; bột mì tạo huyền phù.',
'cơ quan nào của cơ thể thực hiện trao đổi khí?':'Phổi là nơi trao đổi khí: O₂ đi từ phế nang vào máu, CO₂ từ máu ra ngoài qua phế nang.',
'quá trình nước từ hơi nước ngưng tụ thành giọt nước gọi là:':'Ngưng tụ là quá trình hơi nước chuyển thành nước lỏng khi gặp lạnh. Ví dụ: sương mù, nước đọng trên ly lạnh.',
'sinh vật nào dưới đây là sinh vật sản xuất trong chuỗi thức ăn?':'Sinh vật sản xuất (producer) là thực vật — tự tổng hợp chất hữu cơ từ ánh sáng (quang hợp). Cỏ là ví dụ điển hình.',
'bóng đèn dây tóc biến điện năng thành:':'Bóng đèn dây tóc chuyển điện năng thành cả ánh sáng và nhiệt năng (khoảng 95% là nhiệt, chỉ 5% là ánh sáng).',
'trái đất quay quanh mặt trời hết:':'Trái Đất quay quanh Mặt Trời hết khoảng 365,25 ngày (1 năm). Đây là cơ sở của lịch dương.',
'vật dẫn điện tốt nhất là:':'Kim loại (đồng, nhôm, bạc, vàng) dẫn điện tốt nhờ các electron tự do. Nhựa, thủy tinh, gỗ là chất cách điện.',
'để bảo vệ nguồn nước sạch, cần:':'Xử lý nước thải trước khi xả ra môi trường giúp loại bỏ chất độc hại, bảo vệ nguồn nước sạch.',
'ánh sáng truyền theo đường:':'Trong môi trường đồng nhất (không khí, nước...), ánh sáng truyền theo đường thẳng. Đây là nguyên lý cơ bản của quang học.',
'sự thụ phấn ở thực vật có hoa là quá trình:':'Thụ phấn: hạt phấn từ nhị hoa rơi lên đầu nhụy hoa. Đây là bước đầu tiên để tạo hạt và quả.',
'nam châm hút được vật làm từ:':'Nam châm hút các vật từ tính: sắt, thép, niken, coban. Không hút nhôm, đồng, vàng, nhựa.',
'môi trường sống của cá là:':'Cá là động vật thủy sinh — sống dưới nước, thở bằng mang để lấy oxy hòa tan trong nước.',
'chất dinh dưỡng nào cung cấp nhiều năng lượng nhất?':'Chất béo cung cấp 9 kcal/g — gấp đôi protein và carbohydrate (mỗi loại ~4 kcal/g). Vitamin và khoáng chất không cung cấp năng lượng.',
'vệ tinh tự nhiên của trái đất là:':'Mặt Trăng là vệ tinh tự nhiên duy nhất của Trái Đất, quay quanh Trái Đất với chu kỳ khoảng 27,3 ngày.',

// ═══ LỊCH SỬ & ĐỊA LÝ ════
'thủ đô của việt nam là:':'Hà Nội là thủ đô của Việt Nam từ năm 1010 (Lý Thái Tổ dời đô từ Hoa Lư về Thăng Long).',
'sông nào dài nhất việt nam?':'Sông Mê Kông (Cửu Long) dài nhất chảy qua Việt Nam. Sông Hồng là sông quan trọng nhất miền Bắc.',
'ai là người lãnh đạo cuộc khởi nghĩa hai bà trưng?':'Trưng Trắc và Trưng Nhị — hai chị em họ Trưng — lãnh đạo cuộc khởi nghĩa chống ách đô hộ nhà Hán năm 40 SCN.',
'ngày 2 tháng 9 năm 1945 là ngày gì?':'Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Ba Đình — Việt Nam tuyên bố độc lập. Đây là Ngày Quốc khánh.',
'dãy núi nào là ranh giới tự nhiên giữa việt nam và lào?':'Dãy Trường Sơn (Annamite Range) chạy dọc biên giới Việt - Lào theo hướng Bắc - Nam.',
'đồng bằng sông cửu long nằm ở vùng nào của việt nam?':'Đồng bằng sông Cửu Long nằm ở miền Nam Việt Nam — vùng hạ lưu sông Mê Kông.',
'nhà trần thắng quân nguyên - mông lần thứ nhất vào năm nào?':'Năm 1258, nhà Trần dưới sự chỉ huy của Trần Thái Tông đánh thắng quân Nguyên - Mông lần 1. Lần 2 là 1285, lần 3 là 1288.',
'hà nội nằm bên sông nào?':'Hà Nội nằm bên bờ sông Hồng — con sông lớn nhất miền Bắc Việt Nam.',
'vị vua nào dời đô từ hoa lư về thăng long?':'Năm 1010, vua Lý Thái Tổ (Lý Công Uẩn) dời đô từ Hoa Lư (Ninh Bình) về Thăng Long (Hà Nội ngày nay).',
'phú quốc là đảo lớn nhất của tỉnh nào?':'Phú Quốc là đảo lớn nhất Việt Nam, thuộc tỉnh Kiên Giang, nằm trong vịnh Thái Lan.',
'bác hồ sinh ngày tháng năm nào?':'Chủ tịch Hồ Chí Minh sinh ngày 19 tháng 5 năm 1890 tại làng Kim Liên, Nam Đàn, Nghệ An.',
'việt nam tiếp giáp với những quốc gia nào (trên bộ)?':'Việt Nam có biên giới đất liền với Trung Quốc (phía Bắc), Lào và Campuchia (phía Tây).',
'chiến thắng điện biên phủ diễn ra năm nào?':'Chiến dịch Điện Biên Phủ kết thúc ngày 7/5/1954, đánh dấu sự thất bại của thực dân Pháp và kết thúc chiến tranh Đông Dương.',
'vùng đất nào được mệnh danh là "mái nhà đông dương"?':'Dãy Hoàng Liên Sơn (có đỉnh Fansipan cao 3 143 m) được mệnh danh là "nóc nhà Đông Dương".',
'ngô quyền chiến thắng quân nam hán trên sông nào năm 938?':'Năm 938, Ngô Quyền đánh tan quân Nam Hán trên sông Bạch Đằng bằng cách dùng cọc nhọn và lợi dụng thủy triều.',
'thành phố hồ chí minh còn có tên gọi cũ là:':'Sài Gòn là tên gọi cũ của thành phố Hồ Chí Minh trước năm 1975. Gia Định là tên cũ hơn nữa.',
'nghề trồng lúa nước phổ biến nhất ở đồng bằng nào?':'Đồng bằng sông Cửu Long (lúa gạo xuất khẩu) và sông Hồng (lúa miền Bắc) là hai vựa lúa lớn nhất Việt Nam.',
'vịnh hạ long thuộc tỉnh nào?':'Vịnh Hạ Long thuộc tỉnh Quảng Ninh — được UNESCO công nhận Di sản Thiên nhiên Thế giới hai lần (1994 và 2000).',
'nhà nguyễn - triều đại phong kiến cuối cùng của việt nam - kinh đô đặt tại:':'Nhà Nguyễn (1802-1945) đặt kinh đô tại Huế — thành phố di sản với Đại nội và Lăng tẩm các vua.',
'việt nam thuộc khu vực nào của châu á?':'Việt Nam thuộc khu vực Đông Nam Á — nằm ở bán đảo Đông Dương, tiếp giáp biển Đông.',
'cây cầu nào bắc qua sông hồng nổi tiếng ở hà nội?':'Cầu Long Biên (xây 1899-1902 thời Pháp thuộc) là cây cầu thép lịch sử bắc qua sông Hồng tại Hà Nội.',
'đảo nào thuộc chủ quyền việt nam ở biển đông?':'Quần đảo Trường Sa (và Hoàng Sa) là lãnh thổ thiêng liêng của Việt Nam ở biển Đông.',
'đại tướng võ nguyên giáp chỉ huy chiến dịch lịch sử nào?':'Đại tướng Võ Nguyên Giáp chỉ huy chiến dịch Điện Biên Phủ (1954) — chiến thắng làm rung chuyển thế giới.',
'cột cờ hà nội được xây dựng vào thời đại nào?':'Cột cờ Hà Nội được xây dựng năm 1812 dưới triều vua Gia Long — thời nhà Nguyễn.',
'tây nguyên nổi tiếng với loại nông sản nào?':'Tây Nguyên có điều kiện tự nhiên (đất đỏ bazan, khí hậu mát) lý tưởng trồng cà phê — chiếm tỉ trọng lớn xuất khẩu VN.',
'việt nam có diện tích khoảng bao nhiêu km²?':'Việt Nam có diện tích khoảng 331 212 km² — xếp thứ 65 thế giới về diện tích.',
'biển đông tiếp giáp phía nào của việt nam?':'Biển Đông tiếp giáp phía Đông và phía Nam của Việt Nam — đường bờ biển dài hơn 3 260 km.',
'lễ hội đền hùng tổ chức vào ngày nào âm lịch?':'Lễ Giỗ Tổ Hùng Vương tổ chức vào mùng 10 tháng 3 âm lịch hàng năm tại Phú Thọ.',
'đô thị cổ hội an nằm ở tỉnh nào?':'Đô thị cổ Hội An thuộc tỉnh Quảng Nam — được UNESCO công nhận Di sản Văn hóa Thế giới năm 1999.',
'chiến dịch hồ chí minh giải phóng miền nam năm:':'Chiến dịch Hồ Chí Minh kết thúc ngày 30/4/1975, giải phóng Sài Gòn, thống nhất đất nước.',

// ═══ ĐẠO ĐỨC ════
'khi gặp người lớn tuổi hơn, em nên:':'Chào hỏi lễ phép người lớn tuổi là truyền thống tôn trọng người trên của văn hóa Việt Nam.',
'hành động nào thể hiện lòng biết ơn với thầy cô?':'Học bài đầy đủ, nghe giảng chăm chú là cách thiết thực nhất thể hiện lòng biết ơn và tôn trọng thầy cô.',
'em thấy bạn bị bắt nạt, em nên làm gì?':'Báo với thầy cô hoặc người lớn là cách an toàn và đúng đắn để giúp bạn. Không đứng xem hay bỏ mặc.',
'trung thực nghĩa là:':'Trung thực là đức tính nói thật, không gian dối, dù sự thật có thể không có lợi cho mình.',
'hành động nào thể hiện tiết kiệm?':'Tắt điện khi ra khỏi phòng tiết kiệm điện năng. Đây là thói quen nhỏ nhưng có ý nghĩa lớn với môi trường.',
'khi mắc lỗi, em nên:':'Nhận lỗi thể hiện sự trung thực và dũng cảm. Sửa chữa lỗi giúp ta trưởng thành và tránh lặp lại.',
'bảo vệ môi trường là trách nhiệm của:':'Môi trường là tài sản chung nên bảo vệ là trách nhiệm của mọi người — không phân biệt tuổi tác hay địa vị.',
'khi bạn đang buồn, em nên:':'Quan tâm, hỏi thăm và an ủi bạn thể hiện sự đồng cảm và tình bạn chân thành.',
'quyền được học hành là quyền của:':'Theo Công ước Quyền Trẻ em LHQ, mọi trẻ em trên thế giới đều có quyền được học hành, không phân biệt.',
'hành động nào là vi phạm pháp luật?':'Trộm cắp tài sản là vi phạm pháp luật hình sự — xâm phạm quyền sở hữu của người khác.',
'bình đẳng giữa nam và nữ có nghĩa là:':'Bình đẳng giới: nam và nữ có quyền và cơ hội như nhau trong học tập, làm việc, tham gia xã hội.',
'khi nhận được sự giúp đỡ, em nên:':'Nói cảm ơn là cách thể hiện lòng biết ơn và văn minh trong giao tiếp.',
'ý nghĩa của truyền thống "tôn sư trọng đạo" là:': '"Tôn sư trọng đạo" = kính trọng thầy cô và trân trọng việc học — truyền thống tốt đẹp của dân tộc Việt.',
'em không đồng ý với bạn, em nên:':'Bình tĩnh nêu ý kiến là kỹ năng giao tiếp văn minh. Lắng nghe nhau giúp hiểu và tôn trọng quan điểm khác nhau.',
'công dân có nghĩa vụ gì với tổ quốc?':'Theo Hiến pháp, công dân có nghĩa vụ bảo vệ Tổ quốc, xây dựng đất nước và chấp hành pháp luật.',
'hành vi nào thể hiện sự công bằng?':'Chia phần thưởng theo đóng góp là công bằng — mỗi người nhận đúng với những gì họ đã đóng góp.',
'trẻ em có quyền được bảo vệ khỏi:':'Công ước Quyền Trẻ em: trẻ em có quyền được bảo vệ khỏi mọi hình thức bạo lực và lạm dụng.',
'hành động nào thể hiện trách nhiệm với gia đình?':'Giúp đỡ việc nhà và quan tâm người thân là biểu hiện của tình yêu thương và trách nhiệm trong gia đình.',
'khi thấy người bị tai nạn giao thông, em nên:':'Gọi cấp cứu (113/115) hoặc nhờ người lớn giúp ngay — đây là hành động kịp thời cứu người.',
'vì sao cần bảo vệ tài nguyên thiên nhiên?':'Tài nguyên thiên nhiên (rừng, nước, khoáng sản) có hạn. Bảo vệ để đảm bảo cho thế hệ tương lai cũng được hưởng.',
'khi bị người lạ dụ dỗ, em nên:':'Từ chối và báo ngay với bố mẹ/người thân là cách an toàn nhất bảo vệ bản thân khỏi nguy hiểm.',
'hành động nào thể hiện tình yêu quê hương?':'Giữ gìn và quảng bá văn hóa địa phương là biểu hiện cụ thể, thiết thực của tình yêu quê hương.',
'tại sao cần tôn trọng sự khác biệt giữa mọi người?':'Mỗi người có giá trị riêng. Tôn trọng sự khác biệt tạo ra xã hội hòa hợp và giàu sắc màu.',
'hành vi nào là văn hóa giao thông?':'Dừng xe đúng vạch kẻ đường là hành vi văn hóa và an toàn khi tham gia giao thông.',
'tinh thần đoàn kết có ý nghĩa:':'Đoàn kết tạo sức mạnh tập thể — "một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao".',
'khi thấy bạn chép bài, em nên:':'Giải thích tác hại của việc chép bài (không hiểu bài, thi cử gian lận) và khuyên bạn tự làm là cách giúp bạn đúng đắn.',
'hành động nào thể hiện tinh thần học hỏi?':'Đặt câu hỏi khi chưa hiểu là dấu hiệu của người chủ động học hỏi và muốn hiểu sâu hơn.',
'em nhặt được ví tiền của người khác, em nên:':'Giao nộp hoặc tìm trả người mất là hành động trung thực và nhân ái. Giữ lại là vi phạm đạo đức và pháp luật.',
'tại sao cần học tập tốt?':'Học tập giúp có kiến thức, kỹ năng để phát triển bản thân và đóng góp cho gia đình, xã hội.',
'khoan dung có nghĩa là:':'Khoan dung là tha thứ lỗi lầm của người khác và thông cảm hoàn cảnh của họ — đức tính cao đẹp trong quan hệ người với người.',

// ═══ TIN HỌC ════
'phần mềm nào dùng để soạn thảo văn bản?':'Microsoft Word là phần mềm soạn thảo văn bản phổ biến nhất. Excel dùng làm bảng tính, Paint dùng vẽ ảnh.',
'cpu là viết tắt của:':'CPU = Central Processing Unit (Bộ xử lý trung tâm) — bộ não của máy tính.',
'thiết bị nào là thiết bị đầu ra?':'Màn hình hiển thị kết quả xử lý ra ngoài → đầu ra. Bàn phím và chuột là đầu vào.',
'đơn vị nhỏ nhất của thông tin trong máy tính là:':'Bit (binary digit) là đơn vị nhỏ nhất, mang giá trị 0 hoặc 1. 8 bit = 1 byte.',
'phím nào dùng để xóa ký tự bên trái con trỏ?':'Backspace xóa ký tự bên TRÁI con trỏ. Delete xóa ký tự bên PHẢI con trỏ.',
'thư mục (folder) dùng để:':'Thư mục (folder) dùng để tổ chức và chứa các tệp (file) hoặc thư mục con, giúp quản lý dữ liệu dễ dàng.',
'internet là:':'Internet là mạng máy tính toàn cầu kết nối hàng tỉ thiết bị — cho phép chia sẻ thông tin và giao tiếp.',
'để lưu tệp đang soạn thảo, nhấn tổ hợp phím:':'Ctrl + S = Save (Lưu). Ctrl + C = Copy, Ctrl + V = Paste, Ctrl + Z = Undo.',
'ram là viết tắt của:':'RAM = Random Access Memory (Bộ nhớ truy cập ngẫu nhiên) — lưu trữ tạm thời dữ liệu đang xử lý.',
'phần mềm diệt vi-rút dùng để:':'Phần mềm diệt vi-rút (antivirus) phát hiện, ngăn chặn và loại bỏ các chương trình độc hại (malware, virus).',
'để sao chép văn bản, dùng tổ hợp phím:':'Ctrl + C = Copy (sao chép). Ctrl + X = Cut (cắt), Ctrl + V = Paste (dán), Ctrl + A = Select All.',
'usb (ổ đĩa flash) là thiết bị:':'USB flash drive là thiết bị lưu trữ ngoài — cắm vào cổng USB để lưu và chuyển dữ liệu.',
'ô tính trong excel được xác định bằng:':'Trong Excel, mỗi ô tính được xác định bằng tên cột (chữ cái) + số hàng. Ví dụ: A1, B3, C10.',
'tệp tin (file) có đuôi .jpg thường là:':'Đuôi .jpg (JPEG) là định dạng hình ảnh phổ biến. .doc/.docx = Word, .xlsx = Excel, .mp3 = âm thanh.',
'khi máy tính bị đơ (không phản hồi), có thể thử:':'Ctrl + Alt + Delete mở Task Manager — cho phép đóng chương trình bị treo hoặc khởi động lại máy.',
'hệ điều hành windows do công ty nào phát triển?':'Windows là hệ điều hành do Microsoft phát triển. macOS do Apple, Android/Chrome OS do Google.',
'khi tìm kiếm thông tin trên internet, nên:':'Kiểm tra nguồn và so sánh nhiều nguồn giúp xác minh tính chính xác của thông tin trực tuyến.',
'máy in là thiết bị:':'Máy in xuất dữ liệu từ máy tính ra giấy → thiết bị đầu ra (output device).',
'phần mềm trình chiếu phổ biến là:':'Microsoft PowerPoint là phần mềm tạo bài thuyết trình phổ biến nhất. Word soạn thảo, Excel bảng tính.',
'an toàn thông tin trên mạng nghĩa là:':'An toàn mạng bao gồm bảo vệ thông tin cá nhân, không chia sẻ mật khẩu và thận trọng với người lạ online.',
'1 kb = ? byte':'1 KB (Kilobyte) = 1 024 byte (không phải 1 000 byte — vì máy tính dùng hệ nhị phân: 2¹⁰ = 1 024).',
'ngôn ngữ lập trình nào thường dùng trong dạy lập trình cho trẻ em?':'Scratch là ngôn ngữ lập trình trực quan dùng khối kéo-thả, thiết kế đặc biệt cho trẻ em học lập trình.',
'để chọn tất cả văn bản trong tài liệu, dùng:':'Ctrl + A = Select All (Chọn tất cả). Ctrl + S = Save, Ctrl + F = Find (Tìm), Ctrl + B = Bold.',
'email là viết tắt của:':'Email = Electronic Mail (Thư điện tử) — hệ thống trao đổi tin nhắn qua mạng Internet.',
'màn hình cảm ứng (touchscreen) là thiết bị vừa:':'Màn hình cảm ứng vừa là đầu ra (hiển thị) vừa là đầu vào (nhận lệnh chạm tay) — thiết bị lưỡng dụng.',
'để tìm kiếm nhanh trong tài liệu, dùng tổ hợp phím:':'Ctrl + F = Find (Tìm kiếm). Ctrl + H = Replace (Thay thế), Ctrl + G = Go to (Đến trang).',
'wi-fi cho phép:':'Wi-Fi (Wireless Fidelity) cho phép kết nối Internet không dây — không cần cáp vật lý.',
'phím f5 trong trình chiếu powerpoint dùng để:':'Trong PowerPoint, F5 bắt đầu trình chiếu từ đầu. Shift+F5 bắt đầu từ slide hiện tại.',
'hacker là người:':'Hacker (trong ngữ cảnh tiêu cực) là người xâm nhập trái phép vào hệ thống máy tính để đánh cắp hoặc phá hoại.',
'robot hoạt động được nhờ:':'Robot được điều khiển bởi chương trình máy tính (phần mềm) — thực hiện các lệnh được lập trình sẵn.',

// ═══ ÂM NHẠC ════
'nhạc cụ nào sau đây là nhạc cụ dây?':'Guitar là nhạc cụ dây (gảy dây). Trống là gõ, Sáo là hơi, Trumpet là kèn hơi.',
'khuông nhạc gồm bao nhiêu dòng kẻ?':'Khuông nhạc (bản nhạc) gồm 5 dòng kẻ và 4 khe. Nốt nhạc đặt trên dòng và trong khe.',
'nốt nhạc nào có giá trị ngắn nhất trong các nốt cơ bản?':'Nốt móc đơn (♪) = 1/4 nốt đen = 1/8 nốt trắng. Ngắn hơn nốt đen (1), trắng (2), tròn (4).',
'bài hát "quốc ca việt nam" do ai sáng tác?':'Bài Tiến Quân Ca (Quốc ca Việt Nam) do nhạc sĩ Văn Cao sáng tác năm 1944.',
'khóa sol nằm ở dòng thứ mấy của khuông nhạc?':'Khóa Sol xoắn quanh dòng thứ 2 của khuông nhạc, xác định nốt Sol ở dòng 2.',
'nhịp 2/4 có nghĩa là:':'Nhịp 2/4: tử số 2 = 2 phách mỗi ô nhịp; mẫu số 4 = đơn vị phách là nốt đen (1/4 nốt tròn).',
'nốt nhạc "đô" (c) trên khuông nhạc thường nằm ở:':'Nốt Đô giữa (Middle C) nằm trên dòng phụ thêm ngay bên dưới khuông nhạc treble clef.',
'âm nhạc dân gian việt nam bao gồm thể loại nào?':'Âm nhạc dân gian Việt Nam phong phú: Quan họ (Bắc Ninh), Hò, Lý, Ru con, Dân ca các vùng miền.',
'nhạc cụ nào thuộc bộ hơi?':'Sáo trúc thuộc nhạc cụ hơi — thổi hơi qua lỗ để tạo âm thanh. Violin và Đàn tranh là dây, Piano là phím.',
'dấu lặng đen có giá trị tương đương nốt:':'Dấu lặng đen (✦) = nghỉ trong một nốt đen = 1 phách trong nhịp 2/4 hay 4/4.',
'"đàn tranh" là nhạc cụ truyền thống của:':'Đàn tranh (còn gọi là đàn 16 dây) là nhạc cụ dây gảy truyền thống của Việt Nam.',
'bài hát thiếu nhi "đội kèn tí hon" do ai sáng tác?':'Nhạc sĩ Phong Nhã là tác giả bài "Đội kèn tí hon" và nhiều bài hát thiếu nhi nổi tiếng khác.',
'tốc độ bài nhạc được gọi là:':'Tempo (Nhịp độ) chỉ tốc độ nhanh chậm của bài nhạc, thường đo bằng BPM (beats per minute).',
'nốt tròn có giá trị bằng bao nhiêu nốt đen?':'Nốt tròn = 4 phách = 4 nốt đen = 2 nốt trắng. Đây là nốt có giá trị dài nhất trong ký hiệu cơ bản.',
'piano thuộc loại nhạc cụ nào?':'Piano là nhạc cụ phím — gõ phím → búa gõ dây → tạo âm. Kết hợp cả phím và dây.',
'bài "bài ca người giáo viên nhân dân" do ai sáng tác?':'Nhạc sĩ Hoàng Vân sáng tác bài "Bài ca người giáo viên nhân dân" — bài hát nổi tiếng về nghề giáo.',
'trong bản nhạc, dấu thăng (#) làm nốt nhạc:':'Dấu thăng (#) nâng nốt nhạc lên nửa cung (semitone). Dấu giáng (♭) hạ xuống nửa cung.',
'âm thanh cao thấp của nhạc được gọi là:':'Cao độ (pitch) là độ cao thấp của âm thanh. Giai điệu là sự kết hợp các nốt có cao độ khác nhau.',
'nhạc cụ gõ dùng dùi gõ là:':'Trống là nhạc cụ gõ điển hình — dùng dùi hoặc tay gõ vào mặt trống để tạo âm.',
'hát đúng cao độ và trường độ theo bản nhạc gọi là:':'Hát đúng nhịp (trường độ) và đúng giai điệu (cao độ) là yêu cầu cơ bản khi thực hành âm nhạc.',
'bài hát "chú bộ đội hành quân trong mưa" thuộc thể loại:':'Bài hát về hình ảnh bộ đội, có tiết tấu nhịp nhàng như bước hành quân → nhạc hành khúc/thiếu nhi.',
'khi hát, cần chú ý điều gì quan trọng nhất?':'Hát đúng nhịp, đúng lời và phát âm rõ ràng giúp người nghe hiểu nội dung và cảm nhận bài hát.',
'đàn bầu là nhạc cụ truyền thống độc đáo của việt nam, thuộc nhạc cụ:':'Đàn bầu có một dây duy nhất, gảy bằng que và điều khiển bầu để thay đổi cao độ — nhạc cụ dây độc đáo nhất Việt Nam.',
'nốt si trong âm nhạc tương ứng với nốt nào trong hệ thống quốc tế?':'Hệ Việt Nam: Đô-Rê-Mi-Fa-Sol-La-Si tương ứng hệ quốc tế: C-D-E-F-G-A-B. Nốt Si = B.',
'hát bè là hình thức:':'Hát bè: nhiều người hát các bè (voice parts) khác nhau — hòa âm thành bài hát đa âm phong phú.',
'cường độ trong âm nhạc là:':'Cường độ (dynamic) là độ to nhỏ của âm thanh. Ký hiệu: f (forte=to), p (piano=nhỏ), mf, mp...',
'nhạc cụ nào dùng để giữ nhịp trong dàn nhạc?':'Trống (drums/percussion) giữ nhịp — tạo nền tiết tấu ổn định cho các nhạc cụ khác trong ban nhạc.',
'bài "lên đàng" là bài hát thiếu nhi của tác giả:':'Nhạc sĩ Lưu Hữu Phước sáng tác bài "Lên đàng" — bài hát hào hùng, kêu gọi thanh niên lên đường phục vụ.',
'vạch nhịp trong khuông nhạc dùng để:':'Vạch nhịp (bar line) chia khuông nhạc thành các ô nhịp — mỗi ô nhịp có số phách bằng nhau.',
'hát dân ca bắc bộ điển hình là thể loại:':'Quan họ Bắc Ninh là làn điệu dân ca đặc trưng của vùng Bắc Bộ — được UNESCO công nhận Di sản phi vật thể.',

// ═══ MĨ THUẬT ════
'ba màu cơ bản (màu nguyên) là:':'Ba màu nguyên (primary colors) là Đỏ, Vàng, Xanh dương. Trộn chúng lại được màu thứ cấp.',
'trộn màu đỏ và màu vàng ta được màu:':'Đỏ + Vàng = Cam. Đây là màu thứ cấp (secondary color). Đỏ + Xanh = Tím; Vàng + Xanh = Xanh lá.',
'hội họa là nghệ thuật sử dụng:':'Hội họa dùng màu sắc và đường nét để tạo hình ảnh trên mặt phẳng (giấy, vải, tường...).',
'danh họa leonardo da vinci là người nước nào?':'Leonardo da Vinci (1452-1519) là thiên tài người Ý — danh họa, nhà khoa học, kỹ sư vĩ đại thời Phục hưng.',
'trong bức tranh, yếu tố nào tạo chiều sâu?':'Phối cảnh (perspective/viễn cận): vật ở xa vẽ nhỏ hơn, vật ở gần vẽ lớn hơn — tạo cảm giác không gian 3 chiều trên mặt phẳng.',
'gốm sứ thuộc loại nghệ thuật:':'Gốm sứ là nghệ thuật thủ công - mỹ nghệ: nhào đất sét, tạo hình và nung ở nhiệt độ cao.',
'màu bổ sung (đối lập) của màu đỏ là:':'Trong vòng tròn màu sắc (color wheel), màu bổ sung của đỏ là xanh lá — chúng đứng đối diện nhau.',
'hình thức nghệ thuật nào kết hợp màu sắc lên kính?':'Tranh kính màu (stained glass) dùng các mảnh kính màu ghép lại và chì nối — nổi tiếng ở nhà thờ châu Âu.',
'tranh sơn mài là đặc sản của nước:':'Tranh sơn mài Việt Nam dùng sơn ta (nhựa cây sơn) kết hợp vỏ trứng, vàng, bạc — là di sản nghệ thuật độc đáo.',
'nét cong và nét thẳng trong tranh tạo nên:':'Đường nét (line) là yếu tố cơ bản của hình ảnh — xác định hình dạng và đường viền của vật thể.',
'bức tranh "mona lisa" do ai vẽ?':'Mona Lisa (La Gioconda) do Leonardo da Vinci vẽ khoảng 1503-1519 — tác phẩm hội họa nổi tiếng nhất thế giới.',
'nghệ thuật origami là nghệ thuật:':'Origami (折り紙) là nghệ thuật gấp giấy truyền thống của Nhật Bản — tạo hình động vật, hoa, đồ vật từ giấy.',
'màu nóng thường gợi cảm giác:':'Màu nóng (đỏ, cam, vàng) gợi cảm giác ấm áp, năng lượng, sôi động. Màu lạnh (xanh dương, xanh lá) gợi bình yên.',
'điêu khắc là nghệ thuật tạo hình:':'Điêu khắc (sculpture) tạo hình trong không gian 3 chiều bằng cách chạm, đục, nặn, đúc vật liệu.',
'màu trung tính bao gồm:':'Đen, trắng và xám là màu trung tính (achromatic) — không có sắc màu, chỉ có độ sáng tối.',
'chất liệu nào thường dùng để làm tranh màu nước?':'Tranh màu nước (watercolor) dùng màu nước hòa tan + giấy đặc biệt, tạo hiệu ứng trong suốt, nhẹ nhàng.',
'trong bố cục tranh, điểm nhấn chính thường đặt ở:':'Điểm vàng (golden ratio/rule of thirds) là điểm giao của lưới 3×3 — thu hút mắt nhìn tự nhiên nhất.',
'kỹ thuật in dập nổi (nổi bật) trên giấy gọi là:':'In khắc gỗ (woodblock printing): khắc hình lên gỗ, phết mực, ép lên giấy — kỹ thuật in cổ truyền ở châu Á.',
'hình hộp chữ nhật có bao nhiêu mặt?':'Hình hộp chữ nhật có 6 mặt: 2 mặt trên-dưới, 2 mặt trước-sau, 2 mặt trái-phải.',
'màu xanh dương + màu đỏ = ?':'Xanh dương + Đỏ = Tím (Purple/Violet). Đây là màu thứ cấp khi trộn hai màu nguyên.',
'nghệ thuật thư pháp là nghệ thuật:':'Thư pháp (calligraphy) là nghệ thuật viết chữ đẹp có tính thẩm mỹ cao — phổ biến ở châu Á (Hán, Việt, Nhật, Hàn).',
'tranh đông hồ là tranh dân gian của vùng:':'Tranh Đông Hồ xuất xứ từ làng Đông Hồ, huyện Thuận Thành, tỉnh Bắc Ninh — di sản văn hóa phi vật thể Việt Nam.',
'tỉ lệ vàng trong hội họa thường được gọi là:':'Luật ba phần (Rule of Thirds): chia khung hình thành 9 phần bằng nhau bằng 2 đường ngang và dọc — đặt chủ thể tại điểm giao.',
'khi vẽ chân dung người, bộ phận nào cần chú ý nhất?':'Tỉ lệ và cấu trúc khuôn mặt (mắt ở giữa khuôn mặt, tai ngang tầm mắt) là quan trọng nhất trong vẽ chân dung.',
'sắc độ (value) trong tranh là:':'Value (sắc độ) là mức độ sáng-tối của màu sắc — từ trắng đến đen. Tạo hiệu ứng chiều sâu và khối 3D.',
'danh họa việt nam bùi xuân phái nổi tiếng với tranh về:':'Họa sĩ Bùi Xuân Phái (1920-1988) nổi tiếng với loạt tranh về Phố cổ Hà Nội — gọi là "phố Phái".',
'màu xanh lá + màu vàng = ?':'Xanh lá + Vàng = Xanh lá đậm hơn (vì xanh lá đã là trộn xanh+vàng, thêm vàng → nghiêng về vàng). Trong thực tế tạo màu vàng-xanh hoặc xanh đậm.',
'nghệ thuật nào dùng vải và chỉ màu để tạo hình?':'Thêu ren (embroidery) là nghệ thuật dùng kim và chỉ màu thêu lên vải để tạo hoa văn và hình ảnh.',
'ánh sáng trong tranh thường tạo ra:':'Ánh sáng và bóng đổ (light and shadow) tạo chiều sâu, khối 3D và cảm giác thực tế cho tranh vẽ.',
'khi nhìn tranh, yếu tố đầu tiên thu hút mắt thường là:':'Màu sắc tương phản mạnh và vật thể ở trung tâm bố cục thường là điểm đầu tiên thu hút ánh mắt người xem.',

// ═══ GDTC ════
'trước khi tập thể dục, cần thực hiện:':'Khởi động (warm-up) tăng nhiệt độ cơ thể, tăng lưu lượng máu đến cơ bắp và giảm nguy cơ chấn thương.',
'môn thể thao nào cần lưới?':'Cầu lông (badminton) dùng lưới ngăn cách sân của hai người/đội. Bóng đá dùng cột và lưới khung thành.',
'tư thế đứng đúng là:':'Tư thế đứng đúng: lưng thẳng, vai ngang bằng, cổ thẳng — bảo vệ cột sống và tạo dáng đẹp.',
'chạy bền có lợi ích chính là:':'Chạy bền (aerobic exercise) cải thiện sức bền tim mạch-phổi, giảm mỡ máu và tăng sức khỏe tổng thể.',
'bơi lội có tác dụng gì đối với sức khỏe?':'Bơi lội là môn thể thao toàn thân — rèn luyện tất cả các nhóm cơ, tốt cho tim mạch và không gây áp lực cho khớp.',
'trong bóng đá, thủ môn được phép dùng:':'Thủ môn là cầu thủ duy nhất được dùng tay — nhưng chỉ trong vùng cầu môn của mình.',
'điền kinh bao gồm các môn nào?':'Điền kinh gồm chạy, nhảy (cao, xa, sào) và ném (đẩy tạ, ném lao, ném đĩa).',
'khi bị chấn thương nhẹ ở chân trong khi tập, nên:':'Dừng lại ngay khi bị thương là quan trọng nhất — tiếp tục tập có thể làm nặng thêm. Báo giáo viên để được xử lý.',
'môn thể thao nào sử dụng vợt?':'Tennis (quần vợt) dùng vợt đánh bóng qua lưới. Cầu lông cũng dùng vợt nhưng đánh cầu (shuttlecock) không phải bóng.',
'trong nhảy cao, vật cản cần phải:':'Mục tiêu nhảy cao: vượt qua xà mà không làm xà rơi. Chạm xà nhẹ được phép nếu xà không rơi.',
'khi đi bộ đúng kỹ thuật, chân tiếp đất bằng:':'Kỹ thuật đi bộ đúng: gót chân chạm đất trước, sau đó cả bàn chân — giảm áp lực lên khớp gối.',
'hoạt động thể chất tốt cho sức khỏe cần thực hiện:':'WHO khuyến nghị trẻ em (5-17 tuổi) cần ít nhất 60 phút hoạt động thể chất cường độ vừa-cao mỗi ngày.',
'bóng rổ có đặc điểm gì?':'Bóng rổ: 2 đội × 5 người, ném bóng vào rổ cao 3,05m. Điểm: ném từ ngoài vạch 3 điểm, trong 2 điểm, phạt 1 điểm.',
'giữ vệ sinh khi tập thể thao gồm:':'Tắm và thay quần áo sau khi tập giúp loại bỏ mồ hôi và vi khuẩn, tránh viêm da và mùi hôi.',
'tư thế cầm bút đúng giúp:':'Tư thế ngồi viết đúng (thẳng lưng, khoảng cách mắt-sách 30cm) bảo vệ cột sống và phòng cận thị.',
'trong trò chơi kéo co, yếu tố quan trọng là:':'Kéo co: sức mạnh tập thể quan trọng hơn cá nhân — kéo đồng thời, theo nhịp, trọng tâm thấp sẽ có lợi thế.',
'đội hình hàng ngang dùng trong:':'Đội hình hàng ngang dùng trong thể dục đội hình (formation gymnastics) và các buổi lễ diễu hành.',
'để cải thiện sự dẻo dai, nên tập:':'Bài tập căng cơ (stretching) và yoga cải thiện độ linh hoạt cơ khớp — giúp cơ thể dẻo dai và tránh chấn thương.',
'cầu lông được đánh bằng:':'Cầu lông (badminton) dùng vợt (racket) đánh quả cầu lông (shuttlecock) qua lưới.',
'khởi động đúng cách là:':'Khởi động đúng: bắt đầu nhẹ nhàng (đi bộ, xoay khớp) rồi tăng dần cường độ — 5-10 phút trước khi tập chính.',
'sau khi tập thể dục nặng, cần:':'Hạ nhiệt (cool-down) từ từ giúp nhịp tim trở về bình thường, tránh tụt huyết áp và giảm đau cơ hôm sau.',
'trong giờ thể dục, cần mặc:':'Quần áo thể thao thoáng mát, vừa vặn giúp vận động thoải mái, thoát mồ hôi và tránh bị vướng víu.',
'nhảy dây giúp phát triển:':'Nhảy dây rèn luyện sự phối hợp tay-chân, nhịp điệu, sức bền tim mạch và cơ chân.',
'olympic được tổ chức mấy năm một lần?':'Olympic mùa hè tổ chức 4 năm một lần. Olympic mùa đông cũng 4 năm nhưng lệch 2 năm so với mùa hè.',
'môn thể thao nào là biểu tượng của olympic?':'Điền kinh (athletics) là "nữ hoàng của thể thao" và gắn liền nhất với tinh thần Olympic từ thời cổ đại Hy Lạp.',
'trang phục thể thao cần đặc điểm gì?':'Quần áo thể thao cần: thoải mái (không bó chật), thoáng mát (thấm mồ hôi) và dễ vận động.',
'trò chơi dân gian nào rèn luyện sự khéo léo và phối hợp?':'Nhảy lò cò rèn giữ thăng bằng trên một chân, sự khéo léo và khả năng phối hợp cơ thể.',
'lợi ích của thể dục thể thao định kỳ là:':'Thể dục đều đặn: tăng sức đề kháng, kiểm soát cân nặng, giảm stress và cải thiện tâm trạng.',
'trong bài tập thể dục buổi sáng, thường bắt đầu bằng:':'Bài tập buổi sáng bắt đầu bằng hít thở sâu và động tác khởi động nhẹ để đánh thức cơ thể sau khi ngủ.',
'đi bộ nhanh 30 phút mỗi ngày có lợi ích:':'Đi bộ nhanh 30 phút/ngày giảm nguy cơ tim mạch, kiểm soát cân nặng, tăng mật độ xương và giảm stress.',

// ═══ HĐ TRẢI NGHIỆM ════
'kỹ năng lắng nghe có nghĩa là:':'Lắng nghe tích cực: chú ý, không ngắt lời, giao tiếp mắt và hiểu được ý nghĩa của người nói.',
'khi làm việc nhóm, điều quan trọng nhất là:':'Làm việc nhóm hiệu quả cần mọi người lắng nghe nhau, chia sẻ ý kiến cởi mở và phối hợp tốt.',
'kỹ năng tự quản lý thời gian giúp:':'Quản lý thời gian tốt giúp hoàn thành công việc đúng hạn, giảm stress và có thời gian cho bản thân.',
'khi gặp khó khăn, nên:':'Khi gặp khó khăn: bình tĩnh xác định vấn đề, tìm giải pháp và không ngại nhờ giúp đỡ.',
'trải nghiệm cộng đồng giúp học sinh:':'Hoạt động cộng đồng giúp học sinh phát triển kỹ năng xã hội, ý thức trách nhiệm và lòng đồng cảm.',
'nghề nghiệp nào phù hợp nếu em thích chăm sóc người bệnh?':'Bác sĩ, y tá hoặc điều dưỡng là những nghề trực tiếp chăm sóc sức khỏe cho người bệnh.',
'kỹ năng giải quyết vấn đề gồm các bước:':'Quy trình giải quyết vấn đề: nhận biết vấn đề → phân tích nguyên nhân → đề xuất giải pháp → thực hiện → đánh giá kết quả.',
'hoạt động nào giúp khám phá bản thân?':'Thử các hoạt động mới và phản ánh về cảm nhận giúp khám phá sở thích, điểm mạnh và yếu của bản thân.',
'kỹ năng giao tiếp bao gồm:':'Giao tiếp toàn diện gồm: kỹ năng nói (verbal), lắng nghe, ngôn ngữ cơ thể (non-verbal) và viết.',
'khi tham gia lao động tập thể, em nên:':'Tích cực tham gia và đóng góp hết sức là thái độ đúng đắn trong lao động tập thể — thể hiện tinh thần trách nhiệm.',
'thế nào là sống có trách nhiệm?':'Sống có trách nhiệm: hoàn thành nhiệm vụ được giao, không đổ lỗi và chịu trách nhiệm với hành động của mình.',
'hoạt động nào giúp phát triển kỹ năng sáng tạo?':'Vẽ, viết, xây dựng và thử nghiệm ý tưởng mới là những hoạt động kích thích tư duy sáng tạo.',
'khi em mắc sai lầm, điều quan trọng là:':'Nhận ra sai lầm, sửa chữa và rút ra bài học là cách trưởng thành và tránh lặp lại lỗi tương tự.',
'kỹ năng đặt mục tiêu nghĩa là:':'Đặt mục tiêu SMART: Cụ thể, Đo lường được, Có thể đạt được, Thực tế và Có thời hạn — giúp định hướng hành động.',
'tham gia dọn dẹp trường học giúp học sinh:':'Dọn dẹp trường học giúp ý thức bảo vệ môi trường, tinh thần tập thể và cảm giác tự hào về ngôi trường.',
'điều nào sau đây thể hiện kỹ năng hòa giải?':'Hòa giải: lắng nghe tất cả các bên, tìm điểm chung và đề xuất giải pháp mà cả hai bên có thể chấp nhận.',
'phỏng vấn giả lập (role play) trong học tập giúp:':'Role play mô phỏng tình huống thực tế giúp luyện kỹ năng giao tiếp, ứng xử trong môi trường an toàn.',
'môi trường học tập tốt cần:':'Môi trường học tốt: sạch sẽ, đủ ánh sáng (300-500 lux), nhiệt độ thoải mái và không quá ồn ào.',
'kỹ năng tự học có nghĩa là:':'Tự học: chủ động tìm tài liệu, đặt câu hỏi, tổng hợp kiến thức và thực hành — không cần chờ được nhắc nhở.',
'khi em có ý kiến khác với số đông trong nhóm, em nên:':'Bình tĩnh trình bày ý kiến với lý lẽ rõ ràng, sau đó tôn trọng quyết định chung của nhóm.',
'tham quan thực tế (field trip) mang lại:':'Tham quan thực tế giúp áp dụng kiến thức vào thực tế, mở rộng hiểu biết và phát triển kỹ năng quan sát.',
'kỹ năng quản lý cảm xúc giúp:':'Quản lý cảm xúc: nhận biết cảm xúc của mình, hiểu nguyên nhân và chọn cách phản ứng phù hợp với tình huống.',
'phương pháp học tập hiệu quả bao gồm:':'Học hiệu quả: ôn bài đều đặn (spaced repetition), tóm tắt bằng sơ đồ tư duy và tự kiểm tra — tốt hơn học nhồi nhét.',
'điều gì giúp em trở thành người lãnh đạo tốt?':'Lãnh đạo tốt: lắng nghe ý kiến mọi người, ra quyết định công bằng và truyền cảm hứng cho nhóm bằng gương mẫu.',
'giới thiệu bản thân tốt nghĩa là:':'Giới thiệu bản thân: nói rõ tên, sở thích và điểm mạnh một cách tự tin, ngắn gọn và thân thiện.',
'thế nào là ứng xử văn minh trong lớp học?':'Ứng xử văn minh: giơ tay khi muốn phát biểu, lắng nghe chăm chú và tôn trọng ý kiến của bạn và thầy cô.',
'khi dự án nhóm gặp khó khăn, nên:':'Thảo luận cùng nhau để tìm nguyên nhân và giải pháp — khó khăn chung cần giải quyết chung.',
'trải nghiệm với thiên nhiên mang lại:':'Tiếp xúc thiên nhiên giúp yêu môi trường, giảm stress và phát triển khả năng quan sát, khám phá.',
'kỹ năng thuyết trình tốt đòi hỏi:':'Thuyết trình tốt: chuẩn bị kỹ nội dung, tự tin khi đứng trước đám đông, giao tiếp mắt và điều chỉnh tốc độ nói.',

// ═══ VẬT LÝ ════
'ánh sáng truyền với vận tốc khoảng:':'Vận tốc ánh sáng trong chân không ≈ 300 000 km/s (chính xác là 299 792 458 m/s). Đây là vận tốc giới hạn trong vũ trụ.',
'nhiệt kế đo:':'Nhiệt kế đo nhiệt độ của vật hoặc môi trường. Có nhiều loại: thủy ngân, điện tử, hồng ngoại...',
'đơn vị đo lực là:':'Newton (N) là đơn vị đo lực trong Hệ đo lường SI, đặt theo tên nhà khoa học Isaac Newton.',
'vật liệu nào cách điện tốt?':'Nhựa (polymer) là chất cách điện tốt — không có electron tự do. Dùng làm vỏ bọc dây điện để an toàn.',
'gương phẳng tạo ảnh:':'Gương phẳng tạo ảnh ảo (không hứng được trên màn), bằng vật và đối xứng qua mặt gương.',
'âm thanh truyền được qua:':'Âm thanh là sóng cơ học, truyền được qua mọi môi trường vật chất (rắn, lỏng, khí). Không truyền qua chân không.',
'lực hút của trái đất lên các vật gọi là:':'Trọng lực (hay lực hấp dẫn của Trái Đất) hút mọi vật về phía tâm Trái Đất. Ký hiệu: F = mg.',
'nam châm hút mạnh nhất ở:':'Hai cực (N và S) của nam châm có từ trường mạnh nhất. Giữa thanh từ trường yếu hơn.',
'khi đun nóng, hầu hết các vật:':'Đun nóng → vật nở ra (giãn nở nhiệt). Làm lạnh → vật co lại. Ngoại lệ: nước từ 0°C-4°C co lại khi nóng.',
'pin điện cung cấp năng lượng dưới dạng:':'Pin biến hóa năng thành điện năng qua phản ứng hóa học. Điện năng cung cấp cho các thiết bị điện.',
'mắt nhìn thấy vật vì:':'Mắt nhìn thấy vật vì ánh sáng (từ nguồn sáng) chiếu vào vật → phản xạ → đi vào mắt. Buổi tối không có ánh sáng nên không thấy.',
'bóng đèn dây tóc sáng vì:':'Dòng điện qua dây tóc tungsten (điện trở cao) → dây tóc nóng đỏ lên → phát sáng (bức xạ nhiệt).',
'lực ma sát làm:':'Lực ma sát: chống lại chuyển động → làm chậm vật lại và chuyển cơ năng thành nhiệt năng.',
'nguồn sáng tự nhiên là:':'Mặt Trời là nguồn sáng tự nhiên lớn nhất và quan trọng nhất. Sao cũng là nguồn sáng tự nhiên. Đèn, nến là nguồn sáng nhân tạo.',
'nước đá tan ra là hiện tượng:':'Nóng chảy: chất rắn (nước đá) nhận nhiệt → chuyển thành chất lỏng (nước) ở nhiệt độ không đổi (0°C).',
'cân (cân đĩa) đo:':'Cân đo khối lượng của vật. Đơn vị: gram (g), kilogram (kg). Không nhầm với trọng lượng (đo bằng lực kế).',
'đèn led tiết kiệm điện hơn bóng dây tóc vì:':'LED chuyển 90% điện năng thành ánh sáng, chỉ 10% thành nhiệt. Bóng dây tóc ngược lại — tốn điện.',
'khi hai vật cùng điện tích đưa lại gần nhau:':'Hai điện tích cùng dấu (++ hoặc --) đẩy nhau. Hai điện tích khác dấu (+−) hút nhau — định luật Coulomb.',
'thủy tinh là vật:':'Thủy tinh trong suốt (cho ánh sáng đi qua) và cách điện tốt — không có electron tự do dẫn điện.',
'mặt trăng không tự phát sáng, ta thấy được vì:':'Mặt Trăng phản chiếu ánh sáng Mặt Trời như gương — ta thấy Mặt Trăng sáng là nhờ ánh sáng phản chiếu này.',
'cầu vồng xuất hiện khi:':'Cầu vồng: ánh sáng trắng Mặt Trời qua giọt nước → bị khúc xạ và tán sắc thành 7 màu (đỏ, cam, vàng, lục, lam, chàm, tím).',
'đơn vị đo nhiệt độ thông dụng ở việt nam là:':'Việt Nam dùng độ Celsius (°C). Mỹ dùng Fahrenheit (°F). Trong khoa học dùng Kelvin (K): K = °C + 273.',
'tiếng vang xảy ra khi:':'Tiếng vang: âm thanh truyền đến bề mặt cứng (vách núi, tường) → phản xạ → tai nghe lại sau âm gốc.',
'máy phát điện biến đổi:':'Máy phát điện chuyển cơ năng (quay) thành điện năng nhờ hiện tượng cảm ứng điện từ (Faraday).',
'màu sắc của vật phụ thuộc vào:':'Màu sắc vật = ánh sáng mà vật phản xạ lại. Vật đỏ phản xạ ánh đỏ, hấp thụ các màu khác.',
'dây dẫn điện phổ biến làm từ:':'Đồng và nhôm có điện trở nhỏ và giá thành hợp lý — phổ biến nhất làm dây dẫn điện.',
'lực đàn hồi xuất hiện khi:':'Lực đàn hồi xuất hiện khi vật bị biến dạng (nén/kéo) và muốn trở về hình dạng ban đầu — như lò xo.',
'bóng tối xuất hiện khi:':'Bóng tối hình thành khi vật chắn sáng (opaque) ngăn ánh sáng truyền qua — tạo vùng tối phía sau.',
'chất nào dẫn nhiệt kém nhất?':'Nhựa và cao su là chất cách nhiệt tốt (dẫn nhiệt kém) — dùng làm tay cầm nồi, áo bảo hộ...',
'điện trở trong mạch điện làm:':'Điện trở (resistance) cản trở dòng điện chạy qua mạch, tiêu thụ điện năng và thường chuyển thành nhiệt.',

// ═══ TIẾNG ANH (câu mới lớp 5 batch 2) ════
'she ______ her homework when her mum called her.':'Thì quá khứ tiếp diễn (was/were + V-ing) diễn tả hành động đang xảy ra thì bị ngắt ngang: "was doing". "Called" là hành động ngắt ngang → quá khứ đơn.',
'we ______ to the zoo last sunday.':'Thì quá khứ đơn với "last Sunday" → "went" (quá khứ bất quy tắc của "go").',
'______ you ever eaten japanese food before?':'Thì hiện tại hoàn thành (ever/never) với chủ ngữ "you" → "Have". "Have you ever...?" = Bạn đã từng...chưa?',
'the tallest building in the world is in ______.':'Tòa nhà Burj Khalifa cao nhất thế giới nằm ở Dubai, UAE (United Arab Emirates).',
'she is ______ than her younger sister.':'So sánh hơn của "tall" là "taller" (thêm -er). "More tall" sai — tính từ ngắn không dùng "more".',
'i ______ to music on the way to school every morning.':'Thì hiện tại đơn với "every morning" và "I" → "listen" (nguyên thể không thêm -s).',
'what ______ the weather like yesterday? it was sunny.':'Câu hỏi về thời tiết trong quá khứ dùng "was" (be quá khứ số ít). "Yesterday" = dấu hiệu quá khứ.',
'the children ______ football in the garden now.':'Thì hiện tại tiếp diễn với "now" và chủ ngữ số nhiều "the children" → "are playing".',
'he ______ come to the party because he is ill.':'Chủ ngữ "he" (số ít), phủ định khả năng → "can\'t" (không thể đến vì đang ốm).',
'______ is your favourite colour? — blue.':'"What" hỏi về màu sắc (thứ gì). "Where" hỏi nơi chốn, "How" hỏi cách thức, "Who" hỏi người.',
'she has ______ friends at her new school.':'"Many" dùng với danh từ đếm được số nhiều (friends). "Much" dùng với không đếm được, "little" là ít (đối lập).',
'i am good ______ singing but bad ______ dancing.':'"Good at" và "bad at" là cụm cố định: giỏi về / kém về (something). Be good/bad at + V-ing.',
'we ______ tv every evening before dinner.':'Thì hiện tại đơn với "every evening" và "we" (số nhiều) → "watch" (nguyên thể không thêm -s).',
'______ is the school? — it\'s about 2 km from here.':'"How far" hỏi khoảng cách (2 km). "How long" hỏi thời gian, "How much" hỏi giá, "How often" hỏi tần suất.',
'tom ______ born in 2013.':'"Was born" là cụm cố định trong tiếng Anh: được sinh ra. Chủ ngữ "Tom" (số ít) → "was".',
'there ______ a lot of homework tonight.':'"Homework" là danh từ không đếm được → dùng "is" (số ít). "There is + uncountable noun".',
'she ______ like cats, but she loves dogs.':'Phủ định thì hiện tại đơn với "she" (số ít) → "doesn\'t". "Don\'t" dùng cho I/you/we/they.',
'we use ______ to talk to people far away.':'"A telephone" (điện thoại) dùng để nói chuyện với người ở xa. Ruler = thước, pencil = bút chì, clock = đồng hồ.',
'my school ______ 800 students.':'"Has" là thì hiện tại đơn với "my school" (= it, số ít). "Have" cho I/you/we/they.',
'she put the book ______ the shelf.':'"On" dùng khi đặt vật trên bề mặt: on the shelf (trên kệ). "In" là trong hộp/tủ, "at" là tại địa điểm.',
'how ______ milk do we need? just a little.':'"Much" dùng với danh từ không đếm được (milk = sữa). "Many" với đếm được, "few/little" là ít.',
'______ do you go to school? — by bus.':'"How" hỏi về phương tiện đi lại. "What" hỏi thứ gì, "When" hỏi thời gian, "Why" hỏi lý do.',
'he is ______ to carry that heavy box.':'"Too weak" (quá yếu) → không thể mang. Cấu trúc: too + adj + to + V = quá...để làm...',
'she ______ her teeth twice a day.':'Thì hiện tại đơn với "she" (số ít) → "brushes" (thêm -es sau ch/sh/ss/x/o).',
'the baby ______ when the door slammed.':'Thì quá khứ đơn với "door slammed" (đã đóng) → "cried" (quá khứ của "cry" → y→ied).',
'______ do you study english? — because i love it.':'"Why" hỏi lý do. Câu trả lời "Because I love it" xác nhận câu hỏi lý do.',
'may i ______ a glass of water, please?':'"May I have...?" là mẫu câu lịch sự xin phép. Sau "May I" dùng động từ nguyên thể: "have".',
'she ______ her grandparents every weekend.':'Thì hiện tại đơn với "she" (số ít) và "every weekend" → "visits" (thêm -s).',
'the opposite of "noisy" is ______.':'"Quiet" (yên tĩnh) là trái nghĩa của "noisy" (ồn ào). "Busy" = bận rộn, "loud" = to tiếng (gần nghĩa noisy).',
'i ______ my bike when it started to rain.':'Thì quá khứ tiếp diễn (was + V-ing): "was riding" diễn tả hành động đang xảy ra (đang đạp xe) thì bị ngắt bởi "it started to rain".',
};

async function main() {
  const questions = await p.question.findMany({
    where: { explanation: null, gradeId: 'grade-5' },
    select: { id: true, content: true },
  });
  console.log(`🔍 ${questions.length} câu lớp 5 chưa có giải thích.`);
  let updated = 0, skipped = 0;
  for (const q of questions) {
    const key = q.content.trim().toLowerCase();
    const expl = EXPL[key];
    if (!expl) { skipped++; continue; }
    await p.question.update({ where: { id: q.id }, data: { explanation: expl } });
    updated++;
  }
  console.log(`✅ Đã cập nhật ${updated} câu.`);
  if (skipped > 0) console.log(`⚠  Bỏ qua ${skipped} câu (chưa có giải thích trong map).`);
  const rem = await p.question.count({ where: { explanation: null, gradeId: 'grade-5' } });
  console.log(`📊 Còn lại ${rem} câu lớp 5 chưa có giải thích.`);
}
main().catch(console.error).finally(() => p.$disconnect());
